use crate::keybind::normalize_keybind;
use anyhow::{Context, Result, bail};
use std::{
    fs,
    path::{Path, PathBuf},
    process::Command,
};

fn quoted(path: &Path) -> Result<String> {
    Ok(serde_json::to_string(
        path.to_str().context("Ścieżka musi być UTF-8.")?,
    )?)
}

pub fn overlay(base: &Path, exe: &Path, runtime: &Path, key: &str) -> Result<String> {
    let key = normalize_keybind(key)?;
    Ok(format!(
        "// Generated by screen-answer; do not edit while running.\ninclude {}\nbinds {{\n    {key} repeat=false hotkey-overlay-title=\"Analyze practice question\" {{ spawn {} \"--runtime-dir\" {} \"trigger\"; }}\n}}\n",
        quoted(base)?,
        quoted(exe)?,
        quoted(runtime)?
    ))
}

/// Resolve startup config from the actual compositor (the Nix wrapper may override NIRI_CONFIG).
/// An explicitly IPC-loaded config cannot be queried; --niri-config handles that case.
pub fn discover_config() -> Result<PathBuf> {
    let socket =
        std::env::var("NIRI_SOCKET").context("Brak NIRI_SOCKET — uruchom w sesji Niri.")?;
    let name = Path::new(&socket)
        .file_name()
        .and_then(|s| s.to_str())
        .context("Nieprawidłowy NIRI_SOCKET.")?;
    let pid: u32 = name
        .strip_suffix(".sock")
        .and_then(|s| s.rsplit('.').next())
        .context("Nie można ustalić PID Niri.")?
        .parse()?;
    let cmdline = fs::read(format!("/proc/{pid}/cmdline"))?;
    let args: Vec<_> = cmdline
        .split(|b| *b == 0)
        .map(String::from_utf8_lossy)
        .collect();
    for (i, arg) in args.iter().enumerate() {
        if (*arg == "-c" || *arg == "--config")
            && let Some(path) = args.get(i + 1)
        {
            return absolute_config(path);
        }
        if let Some(path) = arg.strip_prefix("--config=") {
            return absolute_config(path);
        }
    }
    let environ = fs::read(format!("/proc/{pid}/environ"))?;
    let vars: Vec<_> = environ
        .split(|b| *b == 0)
        .map(String::from_utf8_lossy)
        .collect();
    if let Some(path) = vars.iter().find_map(|v| v.strip_prefix("NIRI_CONFIG=")) {
        return absolute_config(path);
    }
    if let Some(path) = vars.iter().find_map(|v| v.strip_prefix("XDG_CONFIG_HOME=")) {
        return absolute_config(&format!("{path}/niri/config.kdl"));
    }
    let home = std::env::var("HOME")?;
    absolute_config(&format!("{home}/.config/niri/config.kdl"))
}

fn absolute_config(path: &str) -> Result<PathBuf> {
    let path = PathBuf::from(path);
    if !path.is_absolute() {
        bail!("Wykryto względną ścieżkę konfiguracji. Podaj --niri-config ze ścieżką absolutną.");
    }
    fs::canonicalize(path).context("Nie można odczytać konfiguracji Niri.")
}

pub fn validate(path: &Path) -> Result<()> {
    let result = Command::new("niri")
        .args(["validate", "--config"])
        .arg(path)
        .output()
        .context("Nie można uruchomić walidacji Niri.")?;
    if !result.status.success() {
        bail!(
            "Niepoprawna konfiguracja/skróty Niri: {}",
            String::from_utf8_lossy(&result.stderr)
        );
    }
    Ok(())
}

fn load(path: &Path) -> Result<()> {
    let result = Command::new("niri")
        .args(["msg", "action", "load-config-file", "--path"])
        .arg(path)
        .output()
        .context("Nie można przeładować konfiguracji Niri.")?;
    if !result.status.success() {
        bail!("Niri odrzucił przeładowanie konfiguracji.");
    }
    Ok(())
}

pub struct Binding {
    base: PathBuf,
    restore_file: PathBuf,
    active: bool,
}

impl Binding {
    pub fn install(runtime: &Path, base: PathBuf, key: &str) -> Result<Self> {
        validate(&base)?;
        let path = runtime.join("niri-overlay.kdl");
        let contents = overlay(&base, &std::env::current_exe()?, runtime, key)?;
        fs::write(&path, contents)?;
        validate(&path)?;
        let restore_file = runtime.join("restore-path.json");
        fs::write(&restore_file, serde_json::to_vec(&base)?)?;
        // Mark active first, so Drop restores even if the load operation fails.
        let guard = Self {
            base,
            restore_file,
            active: true,
        };
        load(&path)?;
        Ok(guard)
    }

    pub fn restore(&mut self) -> Result<()> {
        if self.active {
            validate(&self.base)?;
            load(&self.base)?;
            self.active = false;
            let _ = fs::remove_file(&self.restore_file);
        }
        Ok(())
    }
}

impl Drop for Binding {
    fn drop(&mut self) {
        if self.active
            && let Err(err) = self.restore()
        {
            eprintln!("Nie udało się przywrócić skrótu: {err}. Użyj polecenia restore-keybind.");
        }
    }
}

pub fn recover(runtime: &Path) -> Result<()> {
    let path = runtime.join("restore-path.json");
    if !path.exists() {
        return Ok(());
    }
    let base: PathBuf = serde_json::from_slice(&fs::read(&path)?)?;
    validate(&base)?;
    load(&base)?;
    fs::remove_file(path)?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn keybind_validation() {
        assert_eq!(normalize_keybind("PrintScreen").unwrap(), "Print");
        assert_eq!(
            normalize_keybind("control+shift+F8").unwrap(),
            "Ctrl+Shift+F8"
        );
        for key in [
            "",
            "Ctrl+",
            "A;evil",
            "Print\n",
            "Ctrl+Ctrl+A",
            "Foo+F8",
            "\"Print\"",
        ] {
            assert!(normalize_keybind(key).is_err(), "{key}");
        }
    }
    #[test]
    fn paths_are_quoted_and_repeat_is_disabled() {
        let s = overlay(
            Path::new("/base config.kdl"),
            Path::new("/a b/tool"),
            Path::new("/my runtime"),
            "Print",
        )
        .unwrap();
        assert!(s.contains("include \"/base config.kdl\""));
        assert!(s.contains("Print repeat=false"));
        assert!(s.contains("spawn \"/a b/tool\""));
        assert!(!s.contains("allow-when-locked"));
    }
}
